package com.catpuzzle.assistant; import android.accessibilityservice.*;import android.graphics.Path;import android.os.*;import android.view.accessibility.AccessibilityEvent; public class TapAccessibilityService extends AccessibilityService{public static volatile TapAccessibilityService instance; protected void onServiceConnected(){instance=this;} public void onDestroy(){if(instance==this)instance=null;super.onDestroy();} public void onAccessibilityEvent(AccessibilityEvent e){} public void onInterrupt(){} public static boolean tap(float x,float y,int count,long gap){TapAccessibilityService s=instance;if(s==null)return false;new Handler(Looper.getMainLooper()).post(()->s.chain(x,y,count,gap,0));return true;} void chain(float x,float y,int count,long gap,int done){if(done>=count)return;Path p=new Path();p.moveTo(x,y);GestureDescription g=new GestureDescription.Builder().addStroke(new GestureDescription.StrokeDescription(p,0,45)).build();dispatchGesture(g,new GestureResultCallback(){public void onCompleted(GestureDescription gd){new Handler().postDelayed(()->chain(x,y,count,gap,done+1),gap);}},null);}}